SELECT query_id, neighbor_id, rank, distance
FROM cuvs_brute_force_knn(
  dataset => (SELECT id, COALESCE(women, CAST(0 AS REAL)) AS women, COALESCE(toys, CAST(0 AS REAL)) AS toys, COALESCE(kids, CAST(0 AS REAL)) AS kids, COALESCE(men, CAST(0 AS REAL)) AS men, COALESCE(home, CAST(0 AS REAL)) AS home, COALESCE(electronics, CAST(0 AS REAL)) AS electronics, COALESCE(beauty, CAST(0 AS REAL)) AS beauty, COALESCE(vintage, CAST(0 AS REAL)) AS vintage, COALESCE(books, CAST(0 AS REAL)) AS books, COALESCE(sports, CAST(0 AS REAL)) AS sports, COALESCE(other, CAST(0 AS REAL)) AS other, COALESCE(handmade, CAST(0 AS REAL)) AS handmade, COALESCE(garden, CAST(0 AS REAL)) AS garden, COALESCE(arts, CAST(0 AS REAL)) AS arts, COALESCE(pets, CAST(0 AS REAL)) AS pets, COALESCE(office, CAST(0 AS REAL)) AS office, COALESCE(tools, CAST(0 AS REAL)) AS tools FROM mr_scale_tastes ORDER BY id),
  queries => (SELECT id, COALESCE(women, CAST(0 AS REAL)) AS women, COALESCE(toys, CAST(0 AS REAL)) AS toys, COALESCE(kids, CAST(0 AS REAL)) AS kids, COALESCE(men, CAST(0 AS REAL)) AS men, COALESCE(home, CAST(0 AS REAL)) AS home, COALESCE(electronics, CAST(0 AS REAL)) AS electronics, COALESCE(beauty, CAST(0 AS REAL)) AS beauty, COALESCE(vintage, CAST(0 AS REAL)) AS vintage, COALESCE(books, CAST(0 AS REAL)) AS books, COALESCE(sports, CAST(0 AS REAL)) AS sports, COALESCE(other, CAST(0 AS REAL)) AS other, COALESCE(handmade, CAST(0 AS REAL)) AS handmade, COALESCE(garden, CAST(0 AS REAL)) AS garden, COALESCE(arts, CAST(0 AS REAL)) AS arts, COALESCE(pets, CAST(0 AS REAL)) AS pets, COALESCE(office, CAST(0 AS REAL)) AS office, COALESCE(tools, CAST(0 AS REAL)) AS tools FROM mr_scale_tastes ORDER BY id LIMIT 10000),
  k => 10, metric => 'l2_expanded'
)
ORDER BY query_id, rank;
